using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows.Forms;using System.Threading.Tasks;
namespace ScoreModern {public sealed partial class Editor {
 FontAllocationSnapshot fontMetricsSnapshot;FontAllocationWindow fontAllocationWindow;Timer fontMetricsTimer;bool fontMetricsLoading;string fontMetricsRequestedKey;volatile bool fontMetricsDirty=true;readonly List<FileSystemWatcher> fontMetricsWatchers=new List<FileSystemWatcher>();
 void QueueFontMetricsPreload(){
  if(IsDisposed||!IsHandleCreated)return;
  if(fontAllocationWindow==null){fontAllocationWindow=new FontAllocationWindow(this);fontAllocationWindow.PrepareForDisplay();}
  if(fontMetricsTimer==null){fontMetricsTimer=new Timer{Interval=750};fontMetricsTimer.Tick+=(s,e)=>RefreshFontMetricsCache(false);fontMetricsTimer.Start();Disposed+=(s,e)=>{fontMetricsTimer.Stop();fontMetricsTimer.Dispose();foreach(var watcher in fontMetricsWatchers)watcher.Dispose();if(fontAllocationWindow!=null)fontAllocationWindow.Dispose();};}
  RefreshFontMetricsCache(false);
 }
 void RefreshFontMetricsCache(bool force){
  if(IsDisposed||!IsHandleCreated||fontMetricsLoading)return;string folder=NativeTupletFonts.DirectoryPath??"";string key=source+"|"+NativeLibraryLocation.CacheKey(source)+"|"+folder;if(!force&&!fontMetricsDirty&&fontMetricsRequestedKey==key)return;bool newWatch=fontMetricsRequestedKey!=key;fontMetricsDirty=false;string[] metrics=Enumerable.Range(0,90).Select(n=>NativeLibraryLocation.FileFor(source,"FM"+n.ToString("00")+".PSC")).ToArray();fontMetricsRequestedKey=key;fontMetricsLoading=true;if(newWatch){foreach(var watcher in fontMetricsWatchers)watcher.Dispose();fontMetricsWatchers.Clear();foreach(string dir in metrics.Select(p=>Path.GetDirectoryName(p)).Concat(new[]{folder}).Where(p=>!String.IsNullOrEmpty(p)&&Directory.Exists(p)).Distinct(StringComparer.OrdinalIgnoreCase)){try{var watcher=new FileSystemWatcher(dir){IncludeSubdirectories=String.Equals(dir,folder,StringComparison.OrdinalIgnoreCase),NotifyFilter=NotifyFilters.FileName|NotifyFilters.LastWrite|NotifyFilters.Size|NotifyFilters.DirectoryName};FileSystemEventHandler changed=(s,e)=>{string ext=Path.GetExtension(e.FullPath);if(ext.Equals(".psc",StringComparison.OrdinalIgnoreCase)||ext.Equals(".pfb",StringComparison.OrdinalIgnoreCase)||ext.Equals(".pfa",StringComparison.OrdinalIgnoreCase)||ext.Equals(".afm",StringComparison.OrdinalIgnoreCase)||String.IsNullOrEmpty(ext))fontMetricsDirty=true;};watcher.Changed+=changed;watcher.Created+=changed;watcher.Deleted+=changed;watcher.Renamed+=(s,e)=>fontMetricsDirty=true;watcher.Error+=(s,e)=>fontMetricsDirty=true;watcher.EnableRaisingEvents=true;fontMetricsWatchers.Add(watcher);}catch(IOException){fontMetricsDirty=true;}catch(UnauthorizedAccessException){fontMetricsDirty=true;}}}
  Task.Run(()=>FontAllocationCatalog.Read(key,folder,metrics)).ContinueWith(task=>{if(IsDisposed||!IsHandleCreated)return;try{BeginInvoke(new Action(()=>{fontMetricsLoading=false;if(IsDisposed)return;if(task.IsFaulted){if(fontAllocationWindow!=null)fontAllocationWindow.LoadFailed(task.Exception.GetBaseException().Message);return;}var next=task.Result;string currentKey=source+"|"+NativeLibraryLocation.CacheKey(source)+"|"+(NativeTupletFonts.DirectoryPath??"");if(next.Key!=currentKey){RefreshFontMetricsCache(true);return;}bool changed=fontMetricsSnapshot==null||next.Key!=fontMetricsSnapshot.Key||next.Stamp!=fontMetricsSnapshot.Stamp;fontMetricsSnapshot=next;if(fontAllocationWindow!=null&&(changed||force))fontAllocationWindow.SetSnapshot(next);if(changed&&!Program.CheckMode)QueueMissingPscOffer();}));}catch(InvalidOperationException){}});
 }
 void ShowFontAllocationWindow(int? requested){QueueFontMetricsPreload();if(fontMetricsSnapshot!=null)fontAllocationWindow.SetSnapshot(fontMetricsSnapshot);fontAllocationWindow.SelectAllocation(requested??0);fontAllocationWindow.ShowDialog(this);}
 internal void ReloadFontAllocationCache(){RefreshFontMetricsCache(true);}
 internal string FontMetricCopyFolder{get{return NativeOutputLocation.Folder(source);}}
 internal sealed class FontAllocationPlan {internal List<FontMetricWrite> Changes;internal List<FontAllocation> Choices;}
 internal FontAllocationPlan PrepareFontAllocationChanges(FontAllocation[] rows,FontAllocationSnapshot original,string copyFolder){
  string key=source+"|"+NativeLibraryLocation.CacheKey(source)+"|"+(NativeTupletFonts.DirectoryPath??"");if(original==null||key!=original.Key)throw new InvalidOperationException("The font or LIB folder changed. Reload allocations before saving.");
  var duplicate=rows.Where(r=>r.Name.Length>0).GroupBy(r=>r.Name,StringComparer.Ordinal).FirstOrDefault(g=>g.Count()>1);if(duplicate!=null)throw new InvalidDataException("Allocate "+duplicate.Key+" only once. Move or clear its other allocation first.");
  var changes=new List<FontMetricWrite>();var choices=new List<FontAllocation>();var copies=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);
  foreach(var row in rows){var old=original.Allocations[row.Number];if(row.Name==old.Name&&FontAllocationCatalog.Same(row.Bytes,old.Bytes)&&row.FontPath==old.FontPath)continue;byte[] bytes=row.Bytes;if(row.Name.Length==0)bytes=null;else if(bytes==null){if(row.Name.Length>28)throw new InvalidDataException("FontName exceeds SCORE's 28-character PSC field: "+row.Name);if(String.IsNullOrEmpty(row.Afm)||!File.Exists(row.Afm))throw new InvalidDataException("Select a matching AFM for font "+row.Number.ToString("00")+" ("+row.Name+"). No metrics will be invented.");string input=File.ReadAllText(row.Afm);if(FontconvPscModel.FontName(input)!=row.Name)throw new InvalidDataException("AFM FontName does not match allocation "+row.Number.ToString("00"));var font=original.Fonts.FirstOrDefault(f=>f.Path==row.FontPath&&f.Name==row.Name);if(font==null||!File.Exists(font.Path)||FontAllocationCatalog.Hash(File.ReadAllBytes(font.Path))!=font.Hash)throw new IOException("Selected Type 1 file changed. Refresh the catalog before saving.");bytes=new FontconvPscModel().Convert(input);choices.Add(row);}
   string active=NativeOutputLocation.RequireWritableDestination(source,old.Path);if(!FontAllocationCatalog.Same(bytes,old.Bytes)){changes.Add(new FontMetricWrite{Path=active,Expected=old.Bytes,Data=bytes});if(bytes!=null){string safe=String.Concat(row.Name.Select(c=>Path.GetInvalidFileNameChars().Contains(c)?'_':c)).TrimEnd('.',' ');string copy=Path.Combine(copyFolder,safe+".PSC");if(!String.Equals(copy,active,StringComparison.OrdinalIgnoreCase)){byte[] prior=File.Exists(copy)?File.ReadAllBytes(copy):null;if(!FontAllocationCatalog.Same(prior,bytes)){byte[] existing;if(copies.TryGetValue(copy,out existing)&&!FontAllocationCatalog.Same(existing,bytes))throw new IOException("Different metrics require the same reusable filename: "+copy);if(!copies.ContainsKey(copy)){copies[copy]=bytes;changes.Add(new FontMetricWrite{Path=NativeOutputLocation.RequireWritableDestination(source,copy),Expected=prior,Data=bytes});}}}}}
  }
  return new FontAllocationPlan{Changes=changes,Choices=choices};
 }
 internal void SaveFontAllocations(FontAllocation[] rows,FontAllocationSnapshot original,bool overwrite,FontAllocationWindow owner){
  var plan=PrepareFontAllocationChanges(rows,original,owner.CopyFolder);var changes=plan.Changes;var choices=plan.Choices;
  if(changes.Count==0){owner.Saved("No allocation changes to save.");return;}if(changes.Any(c=>c.Expected!=null)&&!overwrite)throw new IOException("Existing PSC files would be replaced or removed. Enable overwrite and review the confirmation.");
  if(MessageBox.Show(owner,"Apply these PSC changes? Base 35 slots are included. Score documents are not renumbered.\r\n\r\n"+String.Join("\r\n",changes.Select(c=>(c.Data==null?"Remove: ":c.Expected==null?"Create: ":"Replace: ")+c.Path)),"Confirm font allocations",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;
  FontMetricTransaction.Commit(changes);owner.Saved("Saved "+changes.Count+" PSC changes; reusable copies are in "+owner.CopyFolder+".");
  try{foreach(var choice in choices)FontVersionChoices.Select(choice.Name,choice.FontPath);canvas.TextLayout=new ScoreText(source);NativeTupletFonts.ClearResolvedFonts();RefreshTextCaches();RefreshAll(canvas.Selected);}catch(Exception error){Message("PSC files saved; resource refresh needs attention: "+error.Message);}RefreshFontMetricsCache(true);
 }
